import {
  Mesh,
  PlaneGeometry,
  Object3D,
  Texture,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';
import { NodeConfig, NodeContext } from '@/types'; // assumed type declarations

export default function createNode(
  config: NodeConfig,
  ctx: NodeContext
): Object3D {
  // --- Geometry ------------------------------------------------------------
  const geometry = new PlaneGeometry(1, 1);

  // --- Texture --------------------------------------------------------------
  const tex: Texture = ctx.textureLoader.load(
    '/prism-assets/chrome/ceramic-grain.map.png'
  );

  // --- Material (node based) ------------------------------------------------
  const material = new MeshBasicNodeMaterial();
  material.map = texture(tex);
  material.transparent = true;

  // --- Mesh -----------------------------------------------------------------
  const mesh = new Mesh(geometry, material);
  mesh.name = config?.name ?? 'badge-collection';

  // --- Placement ------------------------------------------------------------
  const pos = config?.placement?.position ?? { x: 0, y: 1.6, z: 0 };
  const rot = config?.placement?.rotation ?? { x: 0, y: 0, z: 0 };
  const scl = config?.placement?.scale ?? { x: 1, y: 1, z: 1 };

  mesh.position.set(pos.x, pos.y, pos.z);
  mesh.rotation.set(rot.x, rot.y, rot.z);
  mesh.scale.set(scl.x, scl.y, scl.z);

  // --- Interaction ----------------------------------------------------------
  const timelines: any[] = [];

  const originalY = mesh.position.y;
  const liftAmount = 0.15; // subtle lift per spec

  const handleHover = () => {
    const tl = gsap.to(mesh.position, {
      y: originalY + liftAmount,
      duration: 0.3,
      ease: 'power3.out',
    });
    timelines.push(tl);
  };

  const handleHoverOut = () => {
    const tl = gsap.to(mesh.position, {
      y: originalY,
      duration: 0.2,
      ease: 'power3.out',
    });
    timelines.push(tl);
  };

  const handleClick = () => {
    if (typeof ctx.emit === 'function') {
      ctx.emit('hub-collection.select');
    }
  };

  // Attach handlers to userData
  mesh.userData.handlers = {
    hoverEnter: handleHover,
    hoverLeave: handleHoverOut,
    click: handleClick,
  };

  // --- Data binding placeholder ---------------------------------------------
  // The node does not render textual data, but we store the bound rows for
  // potential downstream usage.
  if (Array.isArray(config?.bindings?.rows)) {
    mesh.userData.rows = config.bindings.rows;
  }

  // --- Cleanup --------------------------------------------------------------
  mesh.userData.cleanup = () => {
    // Dispose Three.js resources
    geometry.dispose();
    material.dispose();
    tex.dispose();

    // Kill GSAP timelines
    timelines.forEach((tl) => {
      if (tl && typeof tl.kill === 'function') tl.kill();
    });
    timelines.length = 0;

    // Remove handlers reference
    mesh.userData.handlers = null;
  };

  return mesh;
}
